function ficha(p){
 document.title=p.n+" | DigiNOSIA";
 $("#ficha").innerHTML=`<section><p class="crumbs"><a href="#proyectos">← Volver a proyectos</a></p>
 <span class="cat">${esc(p.cat)}</span><h1 style="max-width:none">${esc(p.n)}</h1><p class="tags" style="font-size:1.1rem;color:var(--tx2);font-family:var(--body)">${esc(p.d)}</p>
 <div class="fgrid"><div><h2>Qué es</h2><p>${esc(p.sum)}</p><h2>Funcionalidades</h2><ul>${p.f.map(x=>`<li>${esc(x)}</li>`).join("")}</ul><h2>Valor tecnológico</h2><p>${esc(p.v)}</p>${arqHtml(p)}
 ${p.nota?`<p class="note">${esc(p.nota)}</p>`:""}
 <p class="note">Pendiente de completar con evidencias reales: capturas, diagrama de arquitectura y mejoras previstas (separadas de lo ya implementado).</p></div>
 <aside class="side" aria-label="Datos del proyecto"><h3>Estado</h3><p>${badge(p)}</p><h3>Tecnologías</h3>${techs(p)}<h3>Acceso</h3>
 ${acc(p)}${relh(p)}</aside></div>${pn(p)}</section>`;
}
function route(){
 const h=decodeURIComponent(location.hash.slice(1));
 const p=P.find(x=>x.id===h);
 document.body.classList.toggle("in-ficha",!!p);
 if(p){ficha(p);window.scrollTo(0,0);$("#ficha h1").setAttribute("tabindex","-1");$("#ficha h1").focus({preventScroll:true})}
 else{showPage(h)}
 document.querySelectorAll("nav a").forEach(a=>a.toggleAttribute("aria-current",a.getAttribute("href")==="#"+(h||"inicio")||(p&&a.getAttribute("href")==="#proyectos")));
 closeMenu();
}
const mb=$("#menu-btn"),menu=$("#menu");
function closeMenu(){menu.classList.remove("open");mb.setAttribute("aria-expanded","false")}
mb.onclick=()=>{const o=menu.classList.toggle("open");mb.setAttribute("aria-expanded",o)};
document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeMenu();$("#a11y").classList.remove("open");$("#a11y-btn").setAttribute("aria-expanded","false")}});
addEventListener("hashchange",route);route();

