function apply(){root.style.setProperty("--fs",pref.fs);pref.theme==="auto"?root.removeAttribute("data-theme"):root.setAttribute("data-theme",pref.theme);try{localStorage.setItem("dg-a11y",JSON.stringify(pref))}catch(e){}}
apply();
const ab=$("#a11y-btn"),panel=$("#a11y"),stt=$("#a11y-status");
ab.onclick=()=>{const o=panel.classList.toggle("open");ab.setAttribute("aria-expanded",o)};
panel.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;
 if(b.dataset.fs){pref.fs=Math.min(1.5,Math.max(.8,+(pref.fs+ +b.dataset.fs).toFixed(2)));stt.textContent="Tamaño del texto: "+Math.round(pref.fs*100)+" %"}
 if(b.dataset.theme){pref.theme=b.dataset.theme;stt.textContent="Tema aplicado"}
 if(b.id==="reset"){pref={fs:1,theme:"auto"};stt.textContent="Preferencias restablecidas"}
 apply()});
