function showPage(h){
 var T={inicio:["inicio","marca","espi","illi","destacados"],proyectos:["proyectos"],especialidades:["especialidades","ilustraciones"],metodologia:["metodologia"],sobre:["sobre"],perfil:["perfil"],contacto:["contacto"]};
 var N={inicio:"Inicio",proyectos:"Proyectos",especialidades:"Especialidades",metodologia:"Metodología",sobre:"Sobre DigiNOSIA",perfil:"Perfil profesional",contacto:"Contacto"};
 if(!T[h])h="inicio";
 document.querySelectorAll("#home>section").forEach(s=>s.classList.toggle("on",T[h].includes(s.id)));
 document.title=h==="inicio"?"DigiNOSIA | Software, Inteligencia Artificial, Datos y Automatización":N[h]+" | DigiNOSIA";
 $("#sr").textContent="Página: "+N[h];
 if(showPage.n){window.scrollTo(0,0);var hd=document.querySelector("#home>section.on h1,#home>section.on h2");if(hd){hd.setAttribute("tabindex","-1");hd.focus({preventScroll:true})}}
 showPage.n=1;
}
function pn(p){var i=P.indexOf(p),a=P[i-1],b=P[i+1];return '<nav class="pn" aria-label="Otros proyectos">'+(a?'<a class="btn" href="#'+a.id+'">← '+esc(a.n)+'</a>':'<span></span>')+(b?'<a class="btn" href="#'+b.id+'">'+esc(b.n)+' →</a>':'')+'</nav>'}

