function flt(){var q=$("#q").value.toLowerCase(),c=$("#cat").value,re=c?new RegExp(c):null,n=0;
 document.querySelectorAll("#cards .card").forEach(el=>{var t=el.textContent,ok=(!q||t.toLowerCase().includes(q))&&(!re||re.test(t));el.hidden=!ok;if(ok)n++});
 $("#count").textContent=n+(n===1?" proyecto":" proyectos")+(n?"":". Prueba con otra búsqueda.")}
$("#q").oninput=flt;$("#cat").onchange=flt;flt();

/* animación al hacer scroll */
var io="IntersectionObserver" in window?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("vis");io.unobserve(e.target)}}),{threshold:.1}):null;
document.querySelectorAll(".card,.steps li,.eco>div").forEach(el=>{el.classList.add("rv");io?io.observe(el):el.classList.add("vis")});
