var CY={lh:["Interlineado",[1.6,1.9,2.2],"--lh",""],ls:["Letras",[0,.05,.1],"--ls","em"],ws:["Palabras",[0,.12,.25],"--ws","em"],ms:["Ancho de línea",[68,56,44],"--measure","ch"]};
var TG={links:"t-links",focus:"t-focus",ruler:"t-ruler",paused:"no-motion",simple:"t-simple",nokeys:""};
function apply2(){var r=document.documentElement;
 for(var k in CY){var c=CY[k];r.style.setProperty(c[2],c[1][Q[k]]+c[3]);document.querySelector('[data-cycle="'+k+'"]').textContent=c[0]+": "+(Q[k]+1)+"/3"}
 r.dataset.font=Q.font;
 ["gray","protan","deutan","tritan"].forEach(f=>r.classList.toggle("f-"+f,Q.filter===f));
 for(var t in TG){var on=Q.t.includes(t);if(TG[t])r.classList.toggle(TG[t],on);document.querySelector('[data-tog="'+t+'"]').setAttribute("aria-pressed",on)}
 $("#p-font").value=Q.font;$("#p-filter").value=Q.filter;$("#p-rate").value=Q.rate;$("#p-voice").value=Q.voice;
 try{localStorage.setItem(K,JSON.stringify(Q))}catch(e){}}
panel.addEventListener("click",e=>{var b=e.target.closest("button");if(!b)return;
 if(b.dataset.cycle){var k=b.dataset.cycle;Q[k]=(Q[k]+1)%3;stt.textContent=CY[k][0]+" actualizado"}
 if(b.dataset.tog){var t=b.dataset.tog,i=Q.t.indexOf(t);i<0?Q.t.push(t):Q.t.splice(i,1);stt.textContent="Opción actualizada"}
 if(b.id==="reset")Q={lh:0,ls:0,ws:0,ms:0,font:"",filter:"",rate:1,voice:"",t:[]};
 if(b.id==="keysbtn")$("#keys").showModal();
 apply2()});
