function vs(){var s=$("#p-voice"),v=speechSynthesis.getVoices().filter(x=>/^es/i.test(x.lang));s.innerHTML='<option value="">Voz predeterminada</option>'+v.map(x=>'<option value="'+esc(x.name)+'">'+esc(x.name)+'</option>').join("");s.value=Q.voice}
if("speechSynthesis" in window){vs();speechSynthesis.onvoiceschanged=vs}
function say(txt){if(!("speechSynthesis" in window)){stt.textContent="Tu navegador no ofrece lectura en voz alta.";return}speechSynthesis.cancel();var u=new SpeechSynthesisUtterance(txt);u.lang="es-ES";u.rate=+Q.rate;var v=speechSynthesis.getVoices().find(x=>x.name===Q.voice);if(v)u.voice=v;speechSynthesis.speak(u)}
$("#read").onclick=()=>{var els=document.body.classList.contains("in-ficha")?[$("#ficha")]:[...document.querySelectorAll("#home>section.on")];say(els.map(e=>e.innerText).join(". ").slice(0,6000));stt.textContent="Leyendo la página"};
