var B=[];
B[0]='<p>Desarrolladora de soluciones digitales con perfil multidisciplinar, orientada a la ingeniería de software, la inteligencia artificial, la automatización, la gestión del conocimiento y el diseño de experiencias digitales.</p><p>Su enfoque combina conocimientos tecnológicos, experiencia en entornos sanitarios y administrativos, capacidad docente y visión funcional de los procesos. Desarrolla herramientas digitales que transforman información compleja en recursos accesibles, estructurados y útiles.</p><blockquote class="quote"><small>Concepto profesional</small>Tecnología, datos y conocimiento aplicados a la resolución de problemas reales, con especial atención a la accesibilidad, la experiencia de usuario y el valor social de las soluciones digitales.</blockquote>';
B[1]='<div class="areas2"><div><div id="ptabs" role="tablist" aria-label="Áreas de conocimiento">'+PB.map((d,k)=>'<button type="button" role="tab" id="tb'+k+'" data-k="'+k+'" aria-controls="tpn'+k+'" aria-selected="'+(k===0)+'" tabindex="'+(k?-1:0)+'" title="'+esc(d[0])+'">'+String.fromCharCode(65+k)+'</button>').join("")+'</div>'+PB.map((d,k)=>'<div class="tp tpanel" role="tabpanel" id="tpn'+k+'" aria-labelledby="tb'+k+'"'+(k?' hidden':'')+'><header><div class="sico">'+sv(d[1])+'</div><h4>'+String.fromCharCode(65+k)+'. '+esc(d[0])+'</h4></header><div class="techs">'+d[2].map((x,j)=>'<span style="--i:'+j+'">'+esc(x)+'</span>').join("")+'</div><p class="orient"><b>Orientación:</b> '+esc(d[3])+'</p></div>').join("")+'</div><figure style="margin:0">'+radar()+'</figure></div>';
