function donut(){var t=AW.reduce((a,b)=>a+b,0),C=2*Math.PI*48,o=0,s="";AW.forEach((w,k)=>{var L=w/t*C;s+=`<circle class="seg" cx="60" cy="60" r="48" stroke="${AC[k]}" stroke-dasharray="${(L-2).toFixed(1)} ${(C-L+2).toFixed(1)}" stroke-dashoffset="${(-o).toFixed(1)}" style="--i:${k}"/>`;o+=L});return `<svg class="donut" viewBox="0 0 120 120" role="img" aria-label="Proyectos por área: ${AK.map((_,k)=>AN[k]+" "+AW[k]).join(", ")}"><g transform="rotate(-90 60 60)">${s}</g><text x="60" y="62" text-anchor="middle" class="dn">7</text><text x="60" y="76" text-anchor="middle" class="dl">áreas</text></svg><div class="chips">${AW.map((w,k)=>`<span>${dot(k,20)}×${w}</span>`).join("")}</div>`}
